pivot = ini;
ini=ini+1;
while (ini <= fim)
if(vetor[ini] <= vetor [pivot])
ini = ini+1;
else {
troca(v, ini, fim);
fim=fim-1;
}
troca(v,pivot,fim);
return fim;
